function templateFor(type){const key=Object.keys(SPECIAL_TEMPLATES).find(k=>type.toLowerCase().includes(k.toLowerCase()) || (k==='Chinese restaurant' && /chinese/i.test(type)) || (k==='Bakery / pastry production' && /bakery/i.test(type)) || (k==='Café / beverages' && /café|cafe|beverage/i.test(type)) || (k==='Fast food' && /fast food/i.test(type)) || (k==='Nigerian food' && /nigerian/i.test(type)) || (k==='Restaurant ambience / customer experience' && /ambience|customer experience/i.test(type)) || (k==='Promotional campaign' && /promotion/i.test(type)) || (k==='Brand storytelling / BTS' && /storytelling|bts/i.test(type)) || (k==='Packaged food product' && /packaged food/i.test(type)) || (k==='Cake product shoot' && /cake product/i.test(type)) || (k==='Cake production / decorating' && /cake production|decorating/i.test(type)) || (k==='General restaurant food' && /general restaurant food/i.test(type)) || (k==='Diner' && /^diner$/i.test(type)) || (k==='Tavern / pub' && /tavern|pub/i.test(type)) || (k==='Grill / BBQ / steakhouse' && /grill|bbq|steakhouse/i.test(type)));return key?SPECIAL_TEMPLATES[key]:[];}

function makeShots(objectives, businessType='Restaurant'){let keys=new Set(objectives.filter(x=>x!=='challenge'));if(!keys.size)keys.add('food');let list=SHOTS.filter(s=>keys.has(s.group)||s.group==='general');const isChinese=/chinese/i.test(businessType), isBakery=/bakery|dessert|food product/i.test(businessType), isCafe=/café|cafe|bar|lounge/i.test(businessType);if(isChinese && keys.has('story'))list=list.filter(s=>true);if(objectives.includes('challenge') && objectives.filter(x=>x!=='challenge').length===0){const preferred=['Exterior establishing wide','Interior reveal — wide','Hero dish — clean static frame','Top-down / overhead food shot','Macro texture close-up','Fork / spoon / chopstick lift','Food served to table','Vertical 9:16 shot with text space','Clean final hero shot'];list=SHOTS.filter(s=>preferred.includes(s.title));}if(objectives.includes('challenge') && objectives.filter(x=>x!=='challenge').length>0){/* Challenge adds no truncation when combined with other objectives. */}const special=templateFor(businessType).map(([title,instruction,tag],i)=>({group:/experience|ambience/i.test(businessType)?'experience':/promotion/i.test(businessType)?'promo':/storytelling|BTS|Chinese restaurant|Bakery|production/i.test(businessType)?'story':'food',title,instruction,tag})); if(special.length && !(objectives.includes('challenge') && objectives.filter(x=>x!=='challenge').length===0)) list=[...list,...special]; return list.map(s=>({...s,id:id(),done:false,custom:false})).filter((s,i,a)=>a.findIndex(x=>x.title===s.title)===i)}
function createProject(){const name=$('#restaurantName').value.trim();if(!name){$('#restaurantName').focus();return}const objectives=selectedObjectives();if(!objectives.length){showToast('Choose at least one shoot objective.');return}const p={id:id(),name,type:$('#restaurantType').value,date:$('#shootDate').value||new Date().toISOString().slice(0,10),objectives,created:new Date().toISOString(),shots:makeShots(objectives,$('#restaurantType').value),status:'active'};data.projects.unshift(p);activeId=p.id;saveData();renderProject();$('#workspace').classList.remove('hidden');$('#setupPanel').classList.add('hidden');$('#workspace').scrollIntoView({behavior:'smooth',block:'start'});}
function activeProject(){return data.projects.find(p=>p.id===activeId)}
function renderProject(){const p=activeProject();if(!p)return;$('#projectTitle').textContent=p.name;$('#projectMeta').textContent=`${p.type} · ${formatDate(p.date)} · ${p.shots.length} shots`;const done=p.shots.filter(s=>s.done).length,total=p.shots.length,percent=total?Math.round(done/total*100):0;$('#progressNumbers').textContent=`${done} / ${total} shots`;$('#progressPercent').textContent=percent+'%';$('#progressBar').style.width=percent+'%';$('#remainingText').textContent=done===total?'All shots captured. Great work!':`${total-done} shot${total-done===1?'':'s'} left to capture`;const groupOrder=['space','food','experience','promo','story','general'];let html='';for(const g of groupOrder){const shots=p.shots.filter(s=>s.group===g);if(!shots.length)continue;const meta=GROUPS[g]||GROUPS.general;const n=shots.filter(s=>s.done).length;html+=`<section class="shot-group"><div class="group-head"><div class="group-title"><span>${meta.icon}</span>${meta.title}</div><span class="group-count">${n}/${shots.length} done</span></div>`;shots.forEach(s=>{const num=p.shots.indexOf(s)+1;html+=`<div class="shot-row ${s.done?'done':''}" id="row-${s.id}"><input class="shot-check" type="checkbox" data-shot="${s.id}" ${s.done?'checked':''} aria-label="Mark ${esc(s.title)} complete"><div class="shot-body"><div class="shot-title">${esc(s.title)} <span class="shot-number">#${String(num).padStart(2,'0')}</span></div><div class="shot-instruction">${esc(s.instruction||'Capture this shot clearly.')}</div>${s.tag?`<span class="shot-tag">${esc(s.tag)}</span>`:''}</div>${s.custom?`<button class="delete-shot" data-delete="${s.id}" aria-label="Delete shot">×</button>`:''}</div>`});html+='</section>'}$('#shotGroups').innerHTML=html;$$('[data-shot]').forEach(el=>el.addEventListener('change',()=>{const shot=p.shots.find(s=>s.id===el.dataset.shot);if(shot){shot.done=el.checked;saveData();renderProject()}}));$$('[data-delete]').forEach(el=>el.addEventListener('click',()=>{p.shots=p.shots.filter(s=>s.id!==el.dataset.delete);saveData();renderProject()}));}
function formatDate(d){if(!d)return 'Date not set';const dt=new Date(d+'T12:00:00');return dt.toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}
function renderRecent(){const el=$('#recentList');if(!data.projects.length){el.innerHTML='<div class="empty-state">Your saved shoots will appear here. Create a shoot above to get started. Shoots are stored in this browser on this device.</div>';return}el.innerHTML=data.projects.slice(0,8).map(p=>{const done=p.shots.filter(s=>s.done).length;return `<div class="recent-item"><div><b>${esc(p.name)}</b><small>${esc(p.type)} · ${formatDate(p.date)}</small></div><span class="recent-progress">${done}/${p.shots.length}</span><div class="recent-actions"><button class="outline-button" data-open="${p.id}">Open</button><button class="outline-button" data-copy="${p.id}">Copy</button></div></div>`}).join('');$$('[data-open]').forEach(b=>b.addEventListener('click',()=>openProject(b.dataset.open)));$$('[data-copy]').forEach(b=>b.addEventListener('click',()=>{const p=data.projects.find(x=>x.id===b.dataset.copy);const c={...p,id:id(),name:p.name+' (copy)',created:new Date().toISOString(),shots:p.shots.map(s=>({...s,id:id(),done:false}))};data.projects.unshift(c);activeId=c.id;saveData();openProject(c.id);showToast('Shoot copied with fresh, unchecked shots.')}))}
function openProject(projectId){activeId=projectId;$('#setupPanel').classList.add('hidden');$('#workspace').classList.remove('hidden');renderProject();$('#workspace').scrollIntoView({behavior:'smooth',block:'start'})}
function showSetup(){activeId=null;editingProjectId=null;$('#workspace').classList.add('hidden');$('#setupPanel').classList.remove('hidden');$('#restaurantName').value='';$('#shootDate').value=new Date().toISOString().slice(0,10);$('#setupPanel').scrollIntoView({behavior:'smooth',block:'start'})}
function exportProject(){const p=activeProject();if(!p)return;let lines=[`SHOT LIST — ${p.name}`,`${p.type} | ${formatDate(p.date)}`,`Progress: ${p.shots.filter(s=>s.done).length}/${p.shots.length} completed`,''];let groups=['space','food','experience','promo','story','general'];groups.forEach(g=>{const ss=p.shots.filter(s=>s.group===g);if(!ss.length)return;lines.push((GROUPS[g]||GROUPS.general).title.toUpperCase());ss.forEach((s,i)=>lines.push(`${s.done?'[x]':'[ ]'} ${s.title} — ${s.instruction}`));lines.push('')});const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${p.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-shot-list.txt`;a.click();URL.revokeObjectURL(a.href);showToast('Checklist exported as a text file.')}
$('#shootForm').addEventListener('submit',e=>{e.preventDefault();if(editingProjectId){const p=data.projects.find(x=>x.id===editingProjectId);if(!p)return;p.name=$('#restaurantName').value.trim();p.type=$('#restaurantType').value;p.date=$('#shootDate').value||p.date;p.objectives=selectedObjectives();saveData();activeId=p.id;editingProjectId=null;$('#setupPanel').classList.add('hidden');$('#workspace').classList.remove('hidden');renderProject();showToast('Shoot details updated.')}else{createProject()}});$('#objectiveChoices').addEventListener('change',e=>{if(e.target.matches('input'))e.target.closest('.mode-card').classList.toggle('selected',e.target.checked)});$('#newShootTop').addEventListener('click',showSetup);$('#editShoot').addEventListener('click',()=>{const p=activeProject();if(!p)return;editingProjectId=p.id;$('#restaurantName').value=p.name;$('#restaurantType').value=p.type;$('#shootDate').value=p.date;$$('#objectiveChoices input').forEach(x=>{x.checked=p.objectives.includes(x.value);x.closest('.mode-card').classList.toggle('selected',x.checked)});$('#setupPanel').classList.remove('hidden');$('#workspace').classList.add('hidden');$('#setupPanel').scrollIntoView({behavior:'smooth',block:'start'});});$('#resetChecks').addEventListener('click',()=>{const p=activeProject();if(!p)return;p.shots.forEach(s=>s.done=false);saveData();renderProject();showToast('All checks reset.')});$('#addShot').addEventListener('click',()=>{$('#shotForm').reset();$('#shotDialog').showModal();$('#shotTitle').focus()});$('#shotForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const p=activeProject();if(!p)return;const title=$('#shotTitle').value.trim();if(!title)return;p.shots.push({id:id(),group:$('#shotGroup').value,title,instruction:$('#shotInstruction').value.trim(),tag:'Custom shot',done:false,custom:true});$('#shotDialog').close();saveData();renderProject();showToast('Shot added to your checklist.')});$('#exportBtn').addEventListener('click',exportProject);$('#exportPdfBtn').addEventListener('click',()=>{if(!activeProject())return;document.body.classList.add('printing-shotlist');window.print();setTimeout(()=>document.body.classList.remove('printing-shotlist'),1000)});$('#finishBtn').addEventListener('click',()=>{const p=activeProject();if(!p)return;p.status='finished';saveData();showToast(p.shots.every(s=>s.done)?'Shoot complete. Nice work!':'Shoot saved. You can return to it any time.');renderProject()});$('#clearHistory').addEventListener('click',()=>{if(!data.projects.length)return;if(confirm('Delete all saved shoots from this browser? This cannot be undone.')){data={projects:[]};activeId=null;saveData();showSetup();showToast('Saved shoot history cleared.')}});
function imageForShot(s){const t=(s.title+' '+(s.tag||'')+' '+(s.instruction||'')).toLowerCase();if(/wok|stir.?fry|noodle|chinese|rice grain/.test(t))return 'photo-1512058564366-18510be2db19';if(/cake|frost|sponge|piping|icing/.test(t))return 'photo-1578985545062-69928b1d9587';if(/bakery|pastry|dough|bread|flour|oven|croissant/.test(t))return 'photo-1509440159596-0249088772ff';if(/coffee|café|cafe|latte|espresso|barista|drink|glass|beverage|ice drop/.test(t))return 'photo-1513558161293-cdaf765edfd7';if(/burger|fries|pizza|fast food|sandwich/.test(t))return 'photo-1565299624946-b28f40a0ae38';if(/grill|bbq|steak|smoke|sear|protein/.test(t))return 'photo-1544025162-d76694265947';if(/restaurant|interior|table|entrance|ambience|menu|customer|staff|service|host|door|sign/.test(t))return 'photo-1517248135467-4c7edcad34c4';if(/package|packaging|label|product|unboxing|variant/.test(t))return 'photo-1542838132-92c53300491e';if(/jollof|nigerian|suya|egusi|swallow|soup|fish|stew|akara|moi moi|pounded yam/.test(t))return 'photo-1547592180-85f173990554';if(/fire|stove|flame|fry|frying|sizzle|chef|kitchen|ingredient|chop|knife|plating|wok|grill/.test(t))return 'photo-1555939594-58d7cb561ad1';return 'photo-1546069901-ba9599a7e63c'}
function renderMoodboard(){const p=activeProject();const board=$('#moodboard');if(!p||!board)return;board.innerHTML=p.shots.map((s,i)=>{const n=i+1;const photo=imageForShot(s);return `<article class="mood-card ${s.done?'done':''}" data-board-shot="${s.id}"><button class="mood-image-button" type="button" data-jump-shot="${s.id}" aria-label="Open shot ${n}: ${esc(s.title)}"><img loading="lazy" src="https://images.unsplash.com/${photo}?auto=format&fit=crop&w=700&q=78" alt="Visual reference for shot ${n}: ${esc(s.title)}" onerror="this.parentElement.classList.add('image-fallback');this.style.display='none'"><span class="image-fallback-label">VISUAL REFERENCE · ${String(n).padStart(2,'0')}</span><span class="mood-number">${String(n).padStart(2,'0')}</span></button><div class="mood-copy"><b>${esc(s.title)}</b><p>${esc(s.instruction||'Capture this shot clearly.')}</p><div class="mood-meta"><span>${esc(s.tag||'Shot reference')}</span><label><input type="checkbox" data-board-check="${s.id}" ${s.done?'checked':''}> Captured</label></div></div></article>`}).join('');$$('[data-jump-shot]').forEach(b=>b.addEventListener('click',()=>{switchView('list');const row=$(`[data-shot="${b.dataset.jumpShot}"]`)?.closest('.shot-row');row?.scrollIntoView({behavior:'smooth',block:'center'});row?.classList.add('focus-shot');setTimeout(()=>row?.classList.remove('focus-shot'),1500)}));$$('[data-board-check]').forEach(c=>c.addEventListener('change',()=>{const s=p.shots.find(x=>x.id===c.dataset.boardCheck);if(s){s.done=c.checked;saveData();renderProject()}}))}
function switchView(which){const list=which==='list';$('#shotGroups').classList.toggle('hidden',!list);$('#moodboard').classList.toggle('hidden',list);$('#listViewBtn').classList.toggle('active',list);$('#boardViewBtn').classList.toggle('active',!list);$('#listViewBtn').setAttribute('aria-selected',String(list));$('#boardViewBtn').setAttribute('aria-selected',String(!list))}
$('#listViewBtn').addEventListener('click',()=>switchView('list'));$('#boardViewBtn').addEventListener('click',()=>switchView('board'));
const originalRenderProject=renderProject;renderProject=function(){originalRenderProject();renderMoodboard()};
$('#shootDate').value=new Date().toISOString().slice(0,10);renderRecent();

